INSERT INTO `system_config` VALUES ('41', 'mail.password-reset.content', '尊敬的 {username} 用户：\r\n\r\n您申请了密码重置，请使用以下验证码重置您的密码：\r\n\r\n验证码：{resetCode}\r\n\r\n或者点击以下链接直接重置密码：\r\n{resetUrl}\r\n\r\n此验证码有效期为{expireMinutes}分钟，请及时操作。\r\n如果您没有申请密码重置，请忽略此邮件。\r\n\r\n{platform}', '密码重置邮件正文模板', '密码重置邮件正文模板。支持变量：{username}（用户名）、{resetCode}（验证码）、{resetUrl}（重置链接）、{expireMinutes}（有效期分钟数）、{platform}（平台名称）', 'textarea', '15', '1', '2025-12-26 22:28:50', '2025-12-26 22:28:50');
INSERT INTO `system_config` VALUES ('42', 'app.platform.name', '趣爱巢商城', '平台名称', '平台名称，用于邮件模板等场景', 'text', '31', '1', '2025-12-26 22:28:50', '2025-12-26 22:28:50');
INSERT INTO `system_config` VALUES ('45', 'payment.record-timeout-hours', '2', '支付记录自动取消时间', '支付中状态的支付记录自动关闭时间（小时），默认2小时。超过此时间仍未完成支付的记录将自动关闭。', 'number', '21', '1', '2025-12-26 23:10:07', '2025-12-26 23:10:07');
INSERT INTO `system_config` VALUES ('46', 'deposit.record-timeout-hours', '1', '预存款记录自动取消时间', '支付中状态的预存款记录自动超时时间（小时），默认1小时。超过此时间仍未完成支付的记录将自动更新为已超时状态。', 'number', '22', '1', '2025-12-26 23:10:27', '2025-12-26 23:10:27');
INSERT INTO `system_config` VALUES ('47', 'wechat.work.webhook.url', '', '企业微信群机器人Webhook URL', '企业微信群机器人的Webhook地址，用于发送订单通知。在企业微信群中添加机器人后获取。格式：https://qyapi.weixin.qq.com/cgi-bin/webhook/send?key=xxxxx', 'textarea', '100', '1', '2025-12-30 22:35:59', '2025-12-30 22:35:59');
INSERT INTO `system_config` VALUES ('48', 'wechat.work.notification.enabled', '1', '企业微信通知开关', '是否启用企业微信通知功能。启用后，用户下单和支付成功时会发送通知到企业微信群。1=启用，0=禁用', 'number', '101', '1', '2025-12-30 22:35:59', '2025-12-30 22:35:59');
